"""`.Cycles no shadows`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Cycles no shadows'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Shader', 'NodeSocketShader')
    t.socket('INPUT', 'Force visibility', 'NodeSocketInt', subtype='FACTOR', min_value=0, max_value=2)
    t.socket('INPUT', 'Dark', 'NodeSocketColor', default_value=(0.5, 0.5, 0.5, 1.0))
    t.socket('INPUT', 'Light', 'NodeSocketColor', default_value=(0.5, 0.5, 0.5, 1.0))
    t.socket('INPUT', 'Normal', 'NodeSocketColor', default_value=(0.5, 0.5, 1.0, 1.0))
    t.socket('INPUT', 'Normal alpha', 'NodeSocketFloat', min_value=0.0, max_value=1.0)
    t.socket('INPUT', 'Normal detail', 'NodeSocketColor')
    t.socket('INPUT', 'Normal detail alpha', 'NodeSocketFloat', min_value=0.0, max_value=1.0)
    t.socket('INPUT', 'Permalight mask', 'NodeSocketColor')
    t.socket('INPUT', 'Alpha mask', 'NodeSocketColor', default_value=(0.8, 0.8, 0.8, 1.0))
    t.socket('INPUT', 'Alpha mask alpha', 'NodeSocketFloat', default_value=0.5, min_value=-10000.0, max_value=10000.0)
    t.socket('INPUT', 'Light alpha', 'NodeSocketInt', subtype='FACTOR', min_value=0, max_value=2)
    t.socket('INPUT', 'Hidden', 'NodeSocketFloat', subtype='FACTOR', min_value=0.0, max_value=1.0)

    t.node('NodeFrame', 'Frame', props={
        'location': (-201.0, -14.0),
        'width': 908.0,
        'height': 216.0,
        'label': 'Cycles shader with no shadows',
        'color': (0.604, 0.604, 0.604),
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (939.7007, -81.21147),
    })
    t.node('NodeGroupInput', 'Group Input', hide_outputs=('Dark', 'Light', 'Normal', 'Normal alpha', 'Normal detail', 'Normal detail alpha', 'Permalight mask', 12), props={
        'location': (-769.3389, -94.77106),
        'width': 187.39368,
    })
    t.node('ShaderNodeGroup', 'AlphaMask Stage Switch', props={
        'node_tree': lib.group('.KK alphamask parser'),
        'location': (-487.2675, -57.786358),
        'width': 251.21655,
        'label': 'AlphaMask Stage Switch',
    })
    t.node('NodeGroupInput', 'Group Input.001', parent='Frame', hide_outputs=('Force visibility', 'Normal', 'Normal alpha', 'Normal detail', 'Normal detail alpha', 'Permalight mask', 'Alpha mask', 'Alpha mask alpha', 'Light alpha', 'Hidden', 12), props={
        'location': (53.357788, -45.257507),
        'width': 187.39368,
    })
    t.node('ShaderNodeBsdfPrincipled', 'Principled BSDF', parent='Frame', inputs={'Roughness': 0.0, 'IOR': 1.45, 'Subsurface Scale': 0.05, 'Specular IOR Level': 0.0, 'Emission Color': (0.0, 0.0, 0.0, 1.0), 'Emission Strength': 1.0}, hide_inputs=('Metallic', 'Roughness', 'IOR', 'Normal', 'Weight', 'Subsurface Weight', 'Subsurface Radius', 'Subsurface Scale', 'Subsurface IOR', 'Subsurface Anisotropy', 'Specular IOR Level', 'Specular Tint', 'Anisotropic', 'Anisotropic Rotation', 'Tangent', 'Transmission Weight', 'Coat Weight', 'Coat Roughness', 'Coat IOR', 'Coat Tint', 'Coat Normal', 'Sheen Weight', 'Sheen Roughness', 'Sheen Tint', 'Emission Color', 'Emission Strength', 'Thin Film Thickness', 'Thin Film IOR'), props={
        'location': (289.3952, -46.96927),
        'distribution': 'GGX',
        'subsurface_method': 'RANDOM_WALK_SKIN',
    })
    t.node('ShaderNodeLightPath', 'Light Path', parent='Frame', hide_outputs=('Is Camera Ray', 'Is Diffuse Ray', 'Is Glossy Ray', 'Is Singular Ray', 'Is Reflection Ray', 'Is Transmission Ray', 'Ray Length', 'Ray Depth', 'Diffuse Depth', 'Glossy Depth', 'Transparent Depth', 'Transmission Depth'), props={
        'location': (578.32874, -41.20929),
        'hide': True,
    })
    t.node('ShaderNodeMixShader', 'Mix Shader.001', parent='Frame', props={
        'location': (738.1789, -56.769043),
    })
    t.node('ShaderNodeBsdfTransparent', 'Transparent BSDF.001', parent='Frame', props={
        'location': (569.8177, -155.17609),
        'hide': True,
    })
    t.node('ShaderNodeValToRGB', 'ColorRamp.001', parent='Frame', outputs={'Color': (0.0, 0.0, 0.0, 0.0)}, color_ramp={'color_mode': 'RGB', 'interpolation': 'LINEAR', 'hue_interpolation': 'NEAR', 'elements': [{'position': 0.935, 'color': (0.0, 0.0, 0.0, 1.0)}, {'position': 1.0, 'color': (1.0, 1.0, 1.0, 1.0)}]}, props={
        'location': (30.48645, -161.49646),
        'hide': True,
    })
    t.node('ShaderNodeBsdfTransparent', 'hidden.transparent', props={
        'location': (539.7007, -231.21147),
        'label': 'hidden.transparent',
    })
    t.node('ShaderNodeMixShader', 'hidden.mix', props={
        'location': (719.7007, -81.21147),
        'label': 'hidden.mix',
    })

    t.link('Group Input', 'Alpha mask alpha', 'AlphaMask Stage Switch', 'Alphamask alpha')
    t.link('Group Input', 'Light alpha', 'AlphaMask Stage Switch', 'Light image alpha')
    t.link('Group Input', 'Force visibility', 'AlphaMask Stage Switch', 'Force visibility?')
    t.link('Group Input', 'Alpha mask', 'AlphaMask Stage Switch', 'Alphamask color')
    t.link('ColorRamp.001', 'Color', 'Principled BSDF', 'Alpha')
    t.link('Principled BSDF', 'BSDF', 'Mix Shader.001', 'Shader')
    t.link('Transparent BSDF.001', 'BSDF', 'Mix Shader.001', 'Shader_001')
    t.link('Light Path', 'Is Shadow Ray', 'Mix Shader.001', 'Fac')
    t.link('AlphaMask Stage Switch', 'Value', 'ColorRamp.001', 'Fac')
    t.link('Group Input.001', 'Light', 'Principled BSDF', 'Base Color')
    t.link('Mix Shader.001', 'Shader', 'hidden.mix', 'Shader')
    t.link('hidden.transparent', 'BSDF', 'hidden.mix', 'Shader_001')
    t.link('Group Input', 'Hidden', 'hidden.mix', 'Fac')
    t.link('hidden.mix', 'Shader', 'Group Output', 'Shader')
    return t
